import { Badge, CardAction, CardDescription, CardHeader, CardTitle } from '@clossys/designer-ui';
import type { GalleryHeaderData } from './types';

/** The agent name, its one-line purpose and how many of its slots are pinned. */
export function GalleryHeader({ header }: { header: GalleryHeaderData }) {
  return <CardHeader className="px-0">
    <CardTitle role="heading" aria-level={1} className="text-xl">{header.title}</CardTitle>
    <CardDescription>{header.description}</CardDescription>
    <CardAction><Badge variant="secondary" data-gallery-pinned="">{header.pinned}</Badge></CardAction>
    {header.notice && <CardDescription><Badge variant="outline">{header.notice}</Badge></CardDescription>}
  </CardHeader>;
}

import { CardContent, CardTitle } from '@clossys/designer-ui';
import { LeafCard } from './LeafCard';
import type { GallerySectionData } from './types';

/** An L2 group: an anchored heading over its slot cards in a responsive grid (1, 2, then 3 columns). */
export function GroupSection({ section }: { section: GallerySectionData }) {
  const heading = `${section.id}-heading`;
  return <section id={section.id} aria-labelledby={heading}>
    <CardTitle id={heading} role="heading" aria-level={2}>{section.label}</CardTitle>
    <CardContent className="grid grid-cols-1 gap-4 px-0 pt-4 md:grid-cols-2 xl:grid-cols-3" data-layout="grid">
      {section.cards.map(card => <LeafCard key={card.key} card={card} level={3} />)}
    </CardContent>
  </section>;
}

import { Badge, Select, SelectContent, SelectItem, SelectTrigger, SelectValue, Tabs, TabsContent, TabsList, TabsTrigger } from '@clossys/designer-ui';
import { GroupSection } from './GroupSection';
import type { GalleryLayerData } from './types';

/**
 * One L0 tab's body: the L1 groups as a vertical tab list with slot counts beside the selected
 * group's cards; below `lg` the list collapses to a select above the content. Only the selected
 * group's panel renders. The list uses the default variant: nested in the L0 tabs, the line
 * variant's indicator also matches the outer horizontal group and collapses to a dot.
 */
export function LayerSection({ layer, group, onGroup }: { layer: GalleryLayerData; group: string; onGroup: (group: string) => void }) {
  return <Tabs orientation="vertical" selectedKey={group} onSelectionChange={key => onGroup(String(key))} className="flex-col gap-4 lg:flex-row lg:gap-6">
    <Select aria-label={layer.label} selectedKey={group} onSelectionChange={key => key !== null && onGroup(String(key))} className="w-full lg:hidden">
      <SelectTrigger><SelectValue /></SelectTrigger>
      <SelectContent>
        {layer.groups.map(row => <SelectItem key={row.id} id={row.id} textValue={row.label}>{row.label}<Badge variant="secondary" className="ml-auto">{row.count}</Badge></SelectItem>)}
      </SelectContent>
    </Select>
    <TabsList aria-label={layer.label} className="hidden w-56 shrink-0 items-stretch self-start lg:flex">
      {layer.groups.map(row => <TabsTrigger key={row.id} id={row.id}>{row.label}<Badge variant="secondary" className="ml-auto">{row.count}</Badge></TabsTrigger>)}
    </TabsList>
    {layer.groups.map(row => <TabsContent key={row.id} id={row.id} className="flex min-w-0 flex-1 flex-col gap-8">
      {row.sections.map(section => <GroupSection key={section.id} section={section} />)}
    </TabsContent>)}
  </Tabs>;
}

import { Badge, Card, CardAction, CardContent, CardDescription, CardHeader, CardTitle, LinkButton, Skeleton } from '@clossys/designer-ui';
import { SpecimenContent } from '../studio-specimen';
import type { GalleryCardData } from './types';

/**
 * One L3 slot as a card: the header names it (a link to its L3 page) with its one state badge;
 * the body is the live preview of the shown state. An empty slot has no body, so its state
 * reads once. Options, history and contract stay on the slot page.
 */
export function LeafCard({ card, level }: { card: GalleryCardData; level: number }) {
  return <Card size="sm" data-gallery-leaf={card.key} data-state={card.state} className="min-w-0">
    <CardHeader>
      <CardTitle role="heading" aria-level={level}>
        <LinkButton href={card.href} variant="link" className="h-auto p-0 text-left whitespace-normal text-foreground">{card.name}</LinkButton>
      </CardTitle>
      <CardAction><Badge variant={card.statusTone}>{card.statusLabel}</Badge></CardAction>
    </CardHeader>
    {card.specimen
      ? <SpecimenContent specimen={card.specimen} />
      : card.specimenStatus?.loading
        ? <CardContent><Skeleton className="aspect-video w-full" aria-label={card.specimenStatus.label} /></CardContent>
        : card.specimenStatus && <CardContent><CardDescription data-preview-status="status">{card.specimenStatus.label}</CardDescription></CardContent>}
  </Card>;
}

import { ScrollArea, Tabs, TabsContent, TabsList, TabsTrigger } from '@clossys/designer-ui';
import { GalleryHeader } from './GalleryHeader';
import { LayerSection } from './LayerSection';
import type { AgentGalleryInput } from './types';

export type { AgentGalleryInput, GalleryCardData, GalleryCardState, GalleryGroupData, GalleryHeaderData, GalleryLayerData, GallerySectionData, GallerySelection, GalleryTone } from './types';

/**
 * `sections.studio.agent-gallery`: the one layout every agent page shares. The header names the
 * agent, its purpose and its pinned count; L0 layers are line tabs (scrolling sideways on narrow
 * screens); each tab lists its L1 groups beside the selected group's L2 headings and slot cards.
 * The page holds the selection (in the URL); the section only lays it out.
 */
export default function AgentGallerySection({ gallery }: { gallery: AgentGalleryInput }) {
  const { layers, selection, onSelect } = gallery;
  const firstGroup = (layer: string) => layers.find(row => row.id === layer)?.groups[0]?.id ?? '';
  return <section data-studio-section="agent-gallery" aria-label={gallery.header.title}>
    <GalleryHeader header={gallery.header} />
    <Tabs selectedKey={selection.layer} onSelectionChange={key => onSelect?.({ layer: String(key), group: firstGroup(String(key)) })} className="gap-6 pt-2">
      <ScrollArea className="-mx-1 px-1 pb-2">
        <TabsList variant="line" aria-label={gallery.header.title}>
          {layers.map(layer => <TabsTrigger key={layer.id} id={layer.id}>{layer.label}</TabsTrigger>)}
        </TabsList>
      </ScrollArea>
      {layers.map(layer => <TabsContent key={layer.id} id={layer.id}>
        <LayerSection layer={layer} group={layer.id === selection.layer ? selection.group : firstGroup(layer.id)} onGroup={group => onSelect?.({ layer: layer.id, group })} />
      </TabsContent>)}
    </Tabs>
  </section>;
}

